from uuid import UUID


def main(payload: dict):
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object")
    for key in ("jobId", "incidentId"):
        UUID(payload[key])
    kind = payload.get("kind")
    if kind not in ("INVESTIGATE", "CONTAIN_SIMULATED"):
        raise ValueError("unsupported workflow kind")
    actor = payload.get("actor")
    if not isinstance(actor, str) or not actor.strip() or len(actor) > 500:
        raise ValueError("invalid evidence actor")
    if kind == "CONTAIN_SIMULATED":
        UUID(payload["responseId"])
        UUID(payload["requestedBy"])
        UUID(payload["approvedBy"])
        if payload.get("approved") is not True or payload["requestedBy"] == payload["approvedBy"]:
            raise ValueError("independent approval required")
    else:
        count = payload.get("failureCount")
        if type(count) is not int or count < 0:
            raise ValueError("invalid failure count")
        ips = payload.get("sourceIps")
        if not isinstance(ips, list) or any(not isinstance(ip, str) for ip in ips):
            raise ValueError("invalid source IP snapshot")
    return payload

import os


def main(payload: dict):
    # This step receives the validated output of the preceding step.
    result = {
        "jobId": payload["jobId"],
        "incidentId": payload["incidentId"],
        "kind": payload["kind"],
        "engine": "WINDMILL",
        "realWorldChanges": False,
    }
    run_id = os.environ.get("WM_ROOT_FLOW_JOB_ID") or os.environ.get("WM_JOB_ID")
    if run_id:
        result["windmillRunId"] = run_id
    if payload["kind"] == "INVESTIGATE":
        count = payload["failureCount"]
        ips = len(set(payload["sourceIps"]))
        result.update({
            "failureCount": count,
            "sourceIpCount": ips,
            "summary": f"Snapshot review: {count} failed logins for {payload['actor']} across {ips} source IPs in {payload.get('windowSeconds', 60)} seconds.",
            "recommendation": "Review the exact event timeline and verify the actor's activity before requesting containment. This is a rule-based snapshot review, not external threat intelligence.",
        })
        if payload.get("evidenceTruncated"):
            result["recommendation"] += " The event evidence snapshot was truncated."
    else:
        result.update({
            "responseId": payload["responseId"],
            "actor": payload["actor"],
            "action": "CONTAIN_ACTOR",
            "mode": "SIMULATION",
            "message": "Windmill completed simulated containment. No real account, network or device was changed.",
        })
    return result
